from collections import namedtuple

from .base import BaseScfcErrorFixer


class _MissingList(
        namedtuple('_MissingList', ['dist_name', 'name'])):

    @staticmethod
    def parse_from(validation_message):
        """Parses matching validation messages"""
        dist_name = validation_message.dist_name
        name = _MissingList._parse_name(validation_message)
        return _MissingList(dist_name, name)

    @staticmethod
    def _parse_name(message):
        return message.text.replace('Incomplete configuration: ', '')


class MissingMandatoryListFixer(BaseScfcErrorFixer):

    def can_fix(self, validation_message):
        """Returns true if this fixer can fix given SCFC validation error/warning, false otherwise"""
        return validation_message.is_error() and validation_message.details.startswith('Mandatory list ')

    def fix(self, validation_message, param_dictionary, scfc):
        """Fixes given SCFC validation error/warning in given SCFC xml using given parameter dictionary xml"""
        missing_list = _MissingList.parse_from(validation_message)
        list_in_dictionary = param_dictionary.get_managed_object(missing_list.dist_name).get_list(missing_list.name)
        managed_object = scfc.find_managed_object(missing_list.dist_name)
        self._add_list_to_managed_object(managed_object, list_in_dictionary)
